do $$ declare r record; begin for r in select p.oid,n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) args from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('quest_add_step','quest_create','quest_set_status','quest_start','quest_record_step','quest_advance_activity','quest_dispatch_event','quest_trigger_geofence','quest_trigger_qr','record_gamification_activity','mark_notification_read','mark_all_notifications_read','register_notification_push_subscription','remove_notification_push_subscription','send_prioritized_notification','send_prioritized_notification_batch','business_send_custom_notification') loop execute format('revoke execute on function %I.%I(%s) from anon',r.nspname,r.proname,r.args); execute format('grant execute on function %I.%I(%s) to authenticated',r.nspname,r.proname,r.args); end loop; end $$;
